"""Editable agent behavior, executed only inside the sandbox.

The optimizer may change this module's prompt, tools, helpers, context management,
and run_agent loop. The runtime supplies model calls, bash execution and logging.
"""
import json
import re
from dataclasses import dataclass

AGENT_INSTRUCTION = 'You are an autonomous terminal agent. You are given a task and a Linux container.\nYou solve tasks by executing bash commands. Work step by step.\n\nRules:\n- Read the task carefully before acting.\n- Explore the environment first to understand what you have.\n- Check command output for errors before proceeding.\n- Install missing dependencies as needed.\n- Verify your solution before finishing.\n- When you believe the task is complete, call the finish tool with a brief summary and the exact bash command that verified the final state.\n- Do not claim completion if your cited verification failed, timed out, or happened before your last change.\n'

TOOLS = [
    {
        'type': 'function',
        'function': {
            'name': 'bash',
            'description': 'Execute a bash command in the container. Returns bounded stdout/stderr plus exit status.',
            'parameters': {
                'type': 'object',
                'properties': {
                    'command': {
                        'type': 'string',
                        'description': 'The bash command to execute.'
                    }
                },
                'required': ['command']
            },
        }
    },
    {
        'type': 'function',
        'function': {
            'name': 'finish',
            'description': 'Declare the task complete only after you already ran a successful final verification command. Provide a short summary, the exact bash verification command you ran, and optionally a literal output excerpt from that command.',
            'parameters': {
                'type': 'object',
                'properties': {
                    'summary': {
                        'type': 'string',
                        'description': 'Brief summary of what you changed or accomplished.'
                    },
                    'verification_command': {
                        'type': 'string',
                        'description': 'The exact bash command from your history that verified the final state.'
                    },
                    'verification_output_excerpt': {
                        'type': 'string',
                        'description': 'Optional exact substring from that command output. Leave empty for silent checks.'
                    }
                },
                'required': ['summary', 'verification_command']
            },
        }
    }
]

_EXIT_RE = re.compile(r'\[exit code:\s*(-?\d+);\s*timed_out:\s*(True|False)\]')


@dataclass
class BashEvent:
    command: str
    output: str
    exit_code: int | None
    timed_out: bool
    is_write: bool
    failed: bool


def _stringify(value):
    if isinstance(value, str):
        return value
    try:
        return json.dumps(value, ensure_ascii=False, sort_keys=True)
    except Exception:
        return str(value)


def _norm_command(text):
    return ' '.join((text or '').split())


def _parse_status(output_text):
    match = _EXIT_RE.search(output_text or '')
    if not match:
        return None, False
    return int(match.group(1)), match.group(2) == 'True'


def _strip_status_footer(output_text):
    return re.sub(r'\n?\[exit code:.*\]\s*$', '', output_text or '', flags=re.S).strip()


def _looks_like_write(command):
    c = _norm_command(command).lower()
    patterns = [
        r'(^|\s)(cat|printf|echo)\b.*>{1,2}',
        r'<<\s*[a-z0-9_\-]+',
        r'\bsed\s+-i\b',
        r'\bperl\s+-pi\b',
        r'\btee\b',
        r'\btouch\b',
        r'\bmkdir\b',
        r'\brm\b',
        r'\bmv\b',
        r'\bcp\b',
        r'\bchmod\b',
        r'\bchown\b',
        r'\bgit\s+(init|clone|commit|push|checkout|switch|branch|merge|rebase|tag)\b',
        r'\b(apt|apt-get|pip|pip3|npm|yarn|pnpm|poetry|cargo)\s+(install|remove|uninstall|add)\b',
        r'(^|[^<])>(?!\()',
    ]
    return any(re.search(pattern, c) for pattern in patterns)


def _record_bash_event(command, output_text):
    exit_code, timed_out = _parse_status(output_text)
    failed = timed_out or (exit_code is not None and exit_code != 0)
    return BashEvent(
        command=command,
        output=output_text,
        exit_code=exit_code,
        timed_out=timed_out,
        is_write=_looks_like_write(command),
        failed=failed,
    )


def _recent_commands(events, limit=5):
    items = []
    for event in events[-limit:]:
        status = 'ok' if not event.failed else 'failed'
        items.append(f'- {status}: {_norm_command(event.command)}')
    return '\n'.join(items) if items else '- none'


def _find_verification_event(events, verification_command):
    target = _norm_command(verification_command)
    if not target:
        return None
    exact = [(i, event) for i, event in enumerate(events) if _norm_command(event.command) == target]
    if exact:
        return exact[-1]
    if len(target) >= 12:
        partial = []
        for i, event in enumerate(events):
            seen = _norm_command(event.command)
            if target in seen or seen in target:
                partial.append((i, event))
        if partial:
            return partial[-1]
    return None


def _validate_finish(args, events):
    summary = args.get('summary')
    verification_command = args.get('verification_command')
    verification_output_excerpt = args.get('verification_output_excerpt', '')

    if not isinstance(summary, str) or not summary.strip():
        return False, 'finish rejected: provide a non-empty summary.'
    if not isinstance(verification_command, str) or not verification_command.strip():
        return False, 'finish rejected: provide the exact bash verification command you already ran successfully.'
    if verification_output_excerpt is None:
        verification_output_excerpt = ''
    if not isinstance(verification_output_excerpt, str):
        return False, 'finish rejected: verification_output_excerpt must be a string.'
    if not events:
        return False, 'finish rejected: no bash commands have been run yet.'

    match = _find_verification_event(events, verification_command)
    if match is None:
        return False, 'finish rejected: the cited verification command was not found in bash history. Recent commands:\n' + _recent_commands(events)

    verify_index, verify_event = match
    if verify_event.timed_out or verify_event.failed:
        return False, 'finish rejected: the cited verification command did not succeed. Re-run a passing final check and cite that exact command.'

    body = _strip_status_footer(verify_event.output)
    if verification_output_excerpt.strip() and verification_output_excerpt not in body:
        return False, 'finish rejected: the provided output excerpt was not found in the cited command output.'

    last_write_index = None
    for i, event in enumerate(events):
        if event.is_write:
            last_write_index = i

    if last_write_index is not None and verify_index < last_write_index:
        return False, 'finish rejected: the cited verification happened before your latest change. Re-run a final check after the most recent write.'

    later_events = events[verify_index + 1:]
    if any(event.is_write for event in later_events):
        return False, 'finish rejected: there were additional changes after the cited verification. Re-run a final verification now.'
    if any(event.failed for event in later_events):
        return False, 'finish rejected: a later bash command failed after the cited verification. Resolve it or re-run verification.'

    if body:
        lines = [line for line in body.splitlines() if line.strip()]
        snippet = lines[-1][:200] if lines else body[:200]
        return True, 'finish approved: cited verification succeeded. Output snippet: ' + snippet
    return True, 'finish approved: cited verification succeeded with exit code 0.'


def run_agent(api, instruction):
    messages = [
        {'role': 'system', 'content': AGENT_INSTRUCTION},
        {'role': 'user', 'content': 'Task:\n' + instruction},
    ]
    events = []
    finish_nudges = 0

    while True:
        message = api.model(messages, TOOLS)
        messages.append(message)
        tool_calls = message.get('tool_calls') or []

        if not tool_calls:
            content = message.get('content')
            if isinstance(content, str) and content.strip():
                finish_nudges += 1
                if finish_nudges <= 2:
                    reminder = 'Before finishing, call the finish tool with a short summary and the exact bash command that verified the final state after your latest change.'
                else:
                    reminder = 'Call finish with your summary and successful verification command, or continue working.'
                messages.append({'role': 'user', 'content': reminder})
            else:
                messages.append({'role': 'user', 'content': 'Continue working with bash. Use finish only after a successful final verification command has already run.'})
            continue

        ordered_calls = []
        ordered_calls.extend([call for call in tool_calls if (call.get('function') or {}).get('name') == 'bash'])
        ordered_calls.extend([call for call in tool_calls if (call.get('function') or {}).get('name') != 'bash'])

        finish_approved = False
        for call in ordered_calls:
            result_text = ''
            try:
                function = call.get('function') or {}
                name = function.get('name')
                args = json.loads(function.get('arguments') or '{}')

                if name == 'bash':
                    command = args.get('command')
                    if not isinstance(command, str) or not command.strip():
                        raise ValueError('Invalid bash tool call: missing command string')
                    raw_result = api.bash(command)
                    result_text = _stringify(raw_result)
                    events.append(_record_bash_event(command, result_text))
                elif name == 'finish':
                    ok, result_text = _validate_finish(args, events)
                    if ok:
                        finish_approved = True
                else:
                    raise ValueError('Invalid tool call: unknown tool')
            except Exception as exc:
                result_text = 'tool error: ' + str(exc)

            api.tool_result(call['id'], result_text)
            messages.append({'role': 'tool', 'tool_call_id': call['id'], 'content': result_text})

        if finish_approved:
            return
